<template><section class="view on"><PageHead title="社区话题" sub="公开帖子引用中的话题不能直接删除"><button class="btn-sage" type="button" @click="create">新建话题</button></PageHead><div class="sheet"><table><thead><tr><th>话题</th><th>帖子</th><th>关注</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.topicId"><td><strong>#{{row.name}}</strong><div class="muted">{{row.description}}</div></td><td>{{row.postCount}}</td><td>{{row.followCount}}</td><td><span class="pill" :class="row.status === 'on' ? 'ok' : 'wait'">{{row.status}}</span></td><td><button class="linkish" type="button" @click="toggle(row)">{{row.status === 'on' ? '停用' : '启用'}}</button><button class="linkish" type="button" @click="remove(row)">删除</button></td></tr><tr v-if="!loading && !rows.length"><td colspan="5"><div class="empty">暂无话题</div></td></tr></tbody></table></div></section></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import PageHead from'@/components/kitchen/PageHead.vue';import{listAdminTopics,createAdminTopic,updateAdminTopic,deleteAdminTopic,type AdminTopic}from'@/api/social';import{toast}from'@/utils/toast';const rows=ref<AdminTopic[]>([]),loading=ref(false);async function load(){loading.value=true;try{rows.value=(await listAdminTopics({page:1,pageSize:100})).data?.list||[]}finally{loading.value=false}}async function create(){const name=window.prompt('话题名称');if(!name)return;try{await createAdminTopic({name,description:'',status:'on',heatWeight:0,sortWeight:0});toast('话题已创建');load()}catch {}}async function toggle(row:AdminTopic){try{await updateAdminTopic(row.topicId,{name:row.name,description:row.description||'',status:row.status==='on'?'off':'on',heatWeight:0,sortWeight:0,version:row.version});load()}catch {}}async function remove(row:AdminTopic){if(!window.confirm('确认停用此话题？'))return;try{await deleteAdminTopic(row.topicId);load()}catch {}}onMounted(load)
</script>
